window.WIKI_T = {"cs": {"navg": {"basics": "Základy", "combat": "Boj", "endgame": "Endgame", "systems": "Systémy", "help": "Pomoc", "gearGrp": "Výbava"}, "nav": {"start": "Než začneš", "path": "Cesta na 300", "at300": "Level 300", "kit": "Základní výbava", "faq": "FAQ", "gear": "Progrese gearu", "boost": "Skill Booster", "rob": "Ring of Blessing", "emb": "Emblemy", "cls": "Hodnocení class", "bld": "Meta buildy", "par": "Paragon", "por": "Portály", "pet": "Peti", "tal": "Talismany", "exp": "Expedice", "pro": "Proroctví", "exa": "Exalted atributy", "mnt": "Mount Companion", "glo": "Slovníček", "maps": "Mapy"}, "hero": {"tag": "Průvodce hrou", "title": "Od prvního levelu po <b>Nalantir</b>", "sub": "Nihor2 se hraje úplně jinak než klasický Metin2. Levely jdou do 300, pak převezme štafetu Paragon. Tohle je celá cesta.", "s1": "Rozsah levelů", "s2": "Strop Paragonu", "s3": "Variant buildů", "s4": "Základních emblemů"}, "s": {"start": {"lead": "Tři věci, které bys měl vědět, než zabiješ první monstrum.", "mountT": "Nikdy nejezdi na mountovi", "mountD": "Mounti na tomhle serveru nejsou užiteční a nikdy nebudou. Na mountovi se pohybuješ i útočíš pomaleji, protože se ořežou hodnoty movement a attack speedu navíc.", "emptyT": "Server vypadá prázdně — není", "emptyD": "Většina hráčů je AFK v Lobby mapě, farmí vyšší mapy nebo sedí v dungeonech. Na začátečnických mapách je ticho záměrně.", "fastT": "Nejrychlejší start", "fastD": "Archer s daggery je momentálně nejjednodušší třída na proběhnutí early game. Hratelné jsou ale všechny — hraj to, co tě baví.", "timeT": "Čas na 300", "timeD": "Zhruba 60 až 90 minut aktivního hraní. Cesta je lineární a není na ní skoro co rozhodovat.", "gearT": "Zatím nekupuj gear", "gearD": "Do Grotto of Exile na levelu 75 nic pořádného nedropneš. Questovní gear ti stačí — šetři Yang."}, "path": {"lead": "Jeď to popořadě. Pokud máš na mapě moc malý damage, vrať se o krok zpátky místo toho, abys to tlačil silou.", "steps": [["Otevři starter chest", "Použij Violet Potion a hned si nasaď XP Ring."], ["Farmi Map 1 do levelu 5–20", "Nic složitého."], ["Switchni Average + Monster", "Sloty 6 a 7, přes Switchbot na <kbd>F6</kbd>."], ["Vyber subclassu, přejdi na Map 2", "Už máš 20+? Jdi rovnou do Valley of Seungryong."], ["Farmi White Eid Bozos do levelu 30", "Portal menu otevřeš přes <kbd>F5</kbd> nebo zelený prstýnek na liště."]], "routeT": "Trasa", "r": {"start": "Starter chest, pak White Eid Bozos ve Valley of Seungryong.", "sd1": "Při vstupu použij Perma Boni Adder z chestu na levelu 1. Ujisti se, že každý kus equipu má 5 bonusů. Volitelně můžeš část přehodit na EXP pro rychlejší leveling.", "sd2": "Před vstupem si u Armor Shop Dealera kup <strong>Lv. 55 Royal Armor +9</strong> a <strong>Lv. 55 Shield +9</strong>.", "g1": "První opravdové upgrady: Lv. 75 zbraně, Lv. 70 armor, doplňky. Dobrá chvíle připravit si 2–3 sety na early dungeony.", "g2": "Víc téhož. Nezastavuj se.", "oc": "Čistě levelovací mapa, nic zvláštního tu nepadá.", "nb": "Pokud damage nestačí, zůstaň ještě chvíli v Old City.", "gc": "Stejné pravidlo — pokud se trápíš, vrať se do Nephrite Bay.", "tm": "Poslední úsek do 300."}, "dieT": "Umíráš často?", "dieD": "Dej si na pár kusů gearu bonusy TP on Hit. Před levelem 75 nepřijdou žádné velké upgrady, takže switchování bonusů je jediná páka, kterou máš."}, "at300": {"lead": "Na levelu 300 teprve začíná skutečná hra. Leveling končí, startuje Paragon.", "unlockT": "Co se odemkne", "unlock": ["Psaní soukromých zpráv ostatním hráčům", "Přístup do Lobby mapy", "První dvě Farm mapy", "Drop Spirit Stones z Metinů", "Upgradování gearu — před 300 nemožné"], "dropT": "Drop z Farm map", "pity": "Pity Items", "fisherT": "Fisher NPC", "fisherD": "Pity Items utratíš u Fishera v Lobby — je v pravém horním rohu mapy. Odtud pocházejí Grandmaster Stones a Rainbow Stones, kterými zvyšuješ ranky skillů.", "farmT": "Kde farmit Yang a upitemy", "farm": ["Nízké dungeony — Razador, Nemere, Jotun Thrym, Blue Death", "Bounties — World a Dungeon varianty", "Owl Runs — emblem chesty a materiály", "Grindování prvních Farm map <em>volitelné</em>"]}, "kit": {"lead": "Společný základ, ke kterému míří každá classa, než začne progression specifický pro tvůj build. Pořadí je doporučení — ceny na trhu s ním zamíchají.", "utilT": "Permanentní utility", "gearT": "Základ gearu", "setbonus": "set bonus", "emb6": "Všech 6 emblemů tvého buildu", "anyroll": "jakýkoli roll", "bigT": "Tři nejdůležitější", "bigD": "<strong>Gold Medal</strong> — výrazně víc Yangu. <strong>Violet Potion</strong> — velký nárůst rychlosti pohybu na vyšších upgradech. <strong>Thief's Gloves</strong> — drop chance nemá reálný strop, takže škáluje pořád dál. Pozor, drop chance nefunguje na chesty ani uvnitř portálů.", "switchT": "Skilly a switchování", "sw": ["P-Skill pro build, který hraješ", "Všechny buff skilly na P", "Weapon a Armor switchnuté na <strong>Skill Damage (27%)</strong> nebo <strong>Average Damage (60%)</strong> podle buildu", "Zbytek equipu switchnutý podle buildu"], "autoT": "Auto loot", "auto": [["Sežeň Companion's Reading", "Kup ho nebo vyrob v Crafting Menu."], ["Vyvolej peta", "Funguje jakýkoli."], ["Přetáhni item na pečeť peta", "Auto loot je aktivní."]], "stoneT": "Spirit Stones", "freeT": "Experimentování zdarma", "freeD": "Spirit Stones se nasazují zvlášť — nejsou vázané na zbraň ani armor, kdykoli je sundáš a výměna vždycky vyjde. Zkoušení různých setupů tě nic nestojí. Zvláštní okno otevřeš v inventáři přes III.", "offT": "Útočné", "defT": "Obranné / utility", "dgT": "Bonusy pro dungeony", "dgH1": "Dungeon", "dgH2": "Bonusy Strong Against"}, "emb": {"lead": "Emblemy jsou nasaditelné itemy, které mění, jak se tvoje classa hraje. Je to největší jednotlivé rozhodnutí o tvé postavě.", "cap": "Co emblemy jsou, odkud padají a jak fungují rolly", "q1": "Co to je?", "a1": "Nasaditelné itemy, které výrazně mění gameplay tvojí classy. Každá classa má 2 sety emblemů po 6 kusech a ty kusy můžeš kombinovat, jak chceš.", "q2": "Kde je sehnat", "a2": "Z Emblem Chestů, které vyrobíš v Crafting Menu (F10) nebo dropneš z Blue Death, Owl Dungeonu a Bounty chestů. Každý chest dá 1 náhodný emblem z 96 základních.", "q3": "Rolly", "a3": "Emblemy mají interní rolly, zobrazené oranžově. Po dropnutí se už nedají změnit — dobrý roll je prostě jiný item než špatný."}, "cls": {"lead": "Hodnocení 0 až 10 podle autora průvodce. Škálovatelnost nezahrnuje jen čistý damage, ale i AoE, projektily a podobně.", "h": {"cls": "Classa", "set": "Set emblemů", "mob": "Clear mobů", "st": "Single target", "metin": "Metin", "spd": "Rychlost", "fun": "Zábava", "note": "Poznámky"}, "n": {"chill": "Klidný styl hry", "mix51": "Potřebuje mix 5|1", "untested": "Neotestováno", "bestst": "Jeden z nejlepších single-target buildů", "needgear": "Potřebuje dobrý gear a emblemy", "brain": "Pokud to tvůj mozek a oči zvládnou", "portal": "Dobrá classa na portály", "twohit": "Musí aspoň 2× zasáhnout, aby to fungovalo", "burst": "Silný burst, průměrný clear", "mix": "Nejlepší hraný v mixu", "rework": "Po reworkách málo informací"}, "opT": "Ber to jako názor", "opD": "Tahle čísla jsou osobní úsudek autora, ne naměřené benchmarky. Ber je jako odrazový můstek, ne jako tier list."}, "bld": {"lead": "Aktuálně hrané sety emblemů. Názvy emblemů zůstávají anglicky, protože tak se zobrazují ve hře.", "x": {"unconf": "Není plně potvrzeno — tohle je setup, který je vidět nejčastěji.", "msura": "Jakmile překročíš 300 INT, vymění Dark Armor za Strengthened Flames.", "norain": "Rain build po posledních změnách Chainu prakticky nikdo nehraje.", "dragearly": "Sežeň si brzy burn damage, ideálně z Burn Damage Spirit Emblemu nebo z Pet Artifactů od P250+. Tohle ti utáhne celou early game.", "dragstar": "Přesouvá těžiště od Burn Damage k Magic Poweru a Starfallu. Pravděpodobně silnější varianta co do damage.", "dragburn": "Alternativa podle preference — klidnější na hraní, o něco nižší strop."}}, "par": {"lead": "Po levelu 300 běží progression přes Paragon levely. Každý level navíc dává +2 Magical Attack Value a P1000 přidá +50 MDEF.", "g": {"g250": "Odemkne Pet Equipment s reálnými bonusy — první velký skok v síle. Zároveň moment, kdy se vyplatí honit dexterity na Ring of Blessing.", "g350": "Otevře se Great Portal. Zpřístupní se Taliko, vstupenky se farmí v Zodiac Desert. Teď už pořádně zvládneš první dvě Paragon mapy.", "g500": "Odsud hlavní motor levelování. Do P500 se dostaň v Zodiac Desert, pak přejdi na Mythic Portaly.", "g650": "Elite portály přinášejí Elite a Super-Elite nepřátele. Otevře se Ape God pro Belt a Pet Bonus Addery. Valley of Apes tě pohodlně vytáhne na P650+.", "g1000": "Heroic Razador, Nemere a Jotun se stávají úplně novými runy, k tomu přibude Platoon. Hlavní zdroj Sigilů a orbů na switchování atributů.", "g1500": "Současný strop zdokumentovaného obsahu."}, "lvlT": "Kde levelovat", "rangeH": "Rozsah", "methH": "Metoda", "m1": "Mythic portály, Stufe ~100–400", "m2": "Jeď Mythic od Stufe 1 tak vysoko, jak zvládneš — ideálně 10k+. Vynese ~50–100 levelů za run", "m3": "Znovu levelovací mapa Orc Valley", "m4": "Paragon Scrolls dropované z portálů", "gearT": "Gear dřív než levely", "gearD": "Pokud nedáš Stufe 100+, makej na gearu místo toho, abys tlačil na P1000. Levely, které neumíš využít, ti nic neotevřou."}, "por": {"lead": "Portály jdou opakovat donekonečna a zůstanou relevantní navždy. Zabíjíš do 100 % dokončení — zhruba 2 000 monster, každý Metin má hodnotu 10 % — pak se objeví boss. Zabiješ ho, opakuješ a Stufe stoupá.", "p": {"pgreat": "Klasická verze. Stufe roste o jedna za každé dokončení.", "pmyth": "Stejná smyčka, ale Stufe roste pokaždé o víc a celkově je to těžší. Nejlepší volba na levelování.", "pelite": "Jako Mythic, navíc musíš kromě 100 % zabít 25 Elite nepřátel — těch, co svítí žlutě."}, "seT": "Super-Elite a Fanny Pack", "seD": "Na <strong>první</strong> mapě každého spuštěného Elite portálu — a jen na první — je malá šance, že se objeví Super-Elite monstrum svítící červeně. Dropuje hodně, včetně honěného itemu: <strong>Fanny Packu</strong>, který zvyšuje počet slotů na Pet Equipment. Tahle šance neškáluje se Stufe, takže je pořád stejná. Jestli se objevilo, zjistíš přes <strong>Magical Orb</strong> vyrobený z Portal Shardů.", "giveT": "Co z portálů máš", "give1": ["Paragon levely", "Green / Blue Gems <em>až 75% Skill nebo 150% Average</em>", "Lapislazuli na Proroctví", "Addery a Switchery na 8. bonus"], "give2": ["Divine Orby a switchovací měnu", "Exotic Equipment", "Exotic Stones", "Pet Equipment"], "hardT": "Začátky bolí", "hardD": "Tenhle obsah je ze začátku hodně těžký — monstra dávají velký damage a mají obrovské TP. Největší jednotlivá páka: <strong>sežeň si Pet Artifacty s Portal Damage.</strong>"}, "pet": {"lead": "Peti se zpřístupní na Paragonu 250 a rychle se z nich stane jeden z nejsilnějších systémů ve hře. Na vyšších levelech ti pet dělá většinu damage.", "cap1": "Základy petů", "cap2": "Sloty na pet equipment", "statT": "Statové body a volba podle classy", "sH1": "Stat", "sH2": "Za bod", "cH1": "Classa / Build", "cH2": "Nejlepší stat peta", "rollT": "Interní rolly rozhodují o všem", "rollD": "Každý bonus peta má interní roll. Pet na levelu 500 s Portal Damage může mít 100 % — nebo 300 %. Dva stejně vypadající peti nejsou tentýž pet.", "goodT": "Dobré rolly na levelu 500", "treeT": "Pet Mastery", "cycT": "Tahle cesta platí jen pro Cyclone", "cycD": "Zdrojový průvodce dokumentuje pořadí mastery pouze pro Cyclone. Neaplikuj ho naslepo na jiné classy.", "cap3": "Strom pet mastery přímo ve hře", "openT": "Úvodní pořadí", "maxT": "Pak maxuj v tomhle pořadí"}, "tal": {"lead": "Talismany dávají bonus Strong vs. Element plus jeden útočný bonus. Je jich šest, nasadíš od každého jeden a sedmý slot drží Talisman Core.", "cap": "Tooltip ze hry", "h1": "Talisman", "h2": "Elementální (+200)", "h3": "Sekundární (+200)", "facts": ["Vyrábí se v Crafting Menu <em>Shardy + hodně Yangu</em>", "Některé stojí až 2,5kkk Yangu", "Upgradovatelné až na +200", "+0 → +200 stojí 20 100 Soulstonů <em>plus spousta Shardů</em>", "Elementální bonus platí na monstra s odpovídajícím elementem — poznáš podle ikonky u HP baru", "Uvnitř portálů podle všeho nefunguje"], "coreT": "Core škáluje podle všech talismanů", "coreD": "Každých 50 levelů zvedne SR rank talismanu a bonus Core závisí na SR ranku <strong>všech šesti</strong>. Abys dostal lepší bonus z Core, potřeboval bys každý talisman na SR1 — a Core nedá vůbec nic, dokud nemáš nasazených všech šest.", "adviceT": "Rada na začátek", "adviceD": "Zatím talismany jen vyrob a trochu upgradni. Nehoň se brzy za vysokými upgrady ani za Core — systém se rychle prodraží."}, "exp": {"lead": "Dlouhodobý systém běžící na pozadí, postavený na levelování Settlerů. Jejich bonusy škálují s levelem, takže dobře vylevelovaný Settler nižšího tieru je mnohem lepší, než napovídají jeho základní hodnoty.", "steps": [["Sežeň zhruba 3 Uncommon Settlery", "Podle toho, kolik máš slotů na Settlery a Pety. Zkus pokrýt Swift, Mighty a Lucky aspoň po jednom."], ["Farmi 1hodinové Easy do levelu 3+", "Krátké runy vylevelují několik Settlerů rychle a úspěšnost zůstává spolehlivá."], ["Přejdi skoro výhradně na 3hodinové Hard", "Tohle se stane tvojí hlavní expediční farmou na pěkně dlouhou dobu."], ["Posbírej klíčové odměny", "Full Adanos, Belt Switcher, Taskaly na použití nebo prodej, expediční peti, hlavní Settleři na levelu 6+."], ["Přesuň se na 6hodinové Hard", "Jeď je, dokud tým nedosáhne 60% úspěšnosti na 12hodinových Hard."], ["Pak 12hodinové, pak 24hodinové Hard", "Stejné pravidlo — posuň se výš, jakmile další tier dosáhne zhruba 60% úspěšnosti."]], "perkT": "Perky Settlerů", "pH1": "Perk", "pH2": "Efekt", "perkN": {"swift": "Swift", "mighty": "Mighty", "lucky": "Lucky", "shadow": "Shadow", "sage": "Sage", "divine": "Divine", "phoenix": "Phoenix"}, "perkD": {"swift": "Zkracuje dobu expedice", "mighty": "Zvyšuje šanci na úspěch expedice", "lucky": "Vylepšuje loot a šanci na vzácné itemy", "shadow": "Kombinace lepšího lootu a rychlosti nebo úspěšnosti, podle konkrétního Settlera", "sage": "Zvyšuje XP získané z expedic", "divine": "Vylepšuje několik statistik naráz — jeden z nejsilnějších univerzálních perků", "phoenix": "Zabraňuje ztrátě XP při neúspěšné expedici"}, "setT": "Seznam Settlerů", "sH1": "Tier", "sH2": "Settler", "sH3": "Perk", "sH4": "Základní hodnota", "tier": {"common": "Common", "uncommon": "Uncommon"}, "ruleT": "Dvě pravidla, co ušetří čas", "ruleD": "Dávej přednost <strong>levelům před výměnou Settlerů</strong> — perky škálují s levelem, takže dobře vylevelovaný nižší tier zůstane užitečný hodně dlouho. A ber <strong>úspěšnost jako svoji bránu</strong>: pokud má další tier nízkou úspěšnost, farmi dál předchozí délku. Rozumný bod pro posun výš je kolem 60 %."}, "pro": {"lead": "Okno Proroctví otevřeš přes Ctrl + P. Každé Lapislazuli dá jedno náhodné proroctví. Lapis padá z monster v jakémkoli portálu — na levelu portálu nezáleží a šance na drop je pořád stejná.", "h1": "Proroctví", "h2": "Efekt", "n": {"emblemmad": "Emblem Madness", "bountyhunt": "Bounty Hunter", "nemere": "Nemere's Dream", "razador": "Razador's Nightmare", "outpower": "Outstanding Power", "outwis": "Outstanding Wisdom", "blacksmith": "Master Blacksmith", "luck": "Exceptional Luck", "blessing": "Jinteia's Blessing", "biggame": "Big-Game Hunting", "astral": "Astral Convergence", "magicwords": "Magic Words"}, "d": {"emblemmad": "Garantuje Emblem Chest z tvého dalšího Blue Death chestu", "bountyhunt": "Zdvojnásobí odměny z dalšího Bounty chestu", "nemere": "Tvoje další zabití Nemere dropne Eternal Ice", "razador": "Tvoje další zabití Razadora dropne Eternal Fire", "outpower": "Další permanentní enchant na zbrani nebo armoru dá aspoň 150 Average Damage", "outwis": "Další permanentní enchant na zbrani nebo armoru dá aspoň 100 Skill Damage", "blacksmith": "Tvůj další pokus o forgnutí nevyžaduje materiály", "luck": "Tvůj další pokus o forgnutí zaručeně vyjde", "blessing": "Další úspěšné forgnutí přeskočí level — +7 jde rovnou na +9", "biggame": "Garantuje Super-Elite v tvém dalším Elite portálu", "astral": "Tvůj další Divine Orb dopadne líp", "magicwords": "Přidá náhodný 9. atribut — existuje skoro pro každý kus equipu"}, "more": "Kromě tohohle seznamu existuje ještě spousta dalších silných proroctví."}, "exa": {"lead": "Systém speciálních atributů navázaný na novou switchovací měnu. Umožní ti rollnout výrazně vyšší hodnoty, překročit běžné stropy a odemknout atributy, které v normálním poolu vůbec nejsou. Místo +12 INT na štítu se můžeš dostat na +40.", "orbN": {"chaos": "Chaos Orb", "annul": "Orb of Annulment", "divine": "Divine Orb", "exalt": "Exalted Orb"}, "orbD": {"chaos": "Přerollne bonusy v rámci Exalted poolu.", "annul": "Odstraní z itemu existující bonus.", "divine": "Zvyšuje tier hodnoty existujících bonusů za běžný strop Tier 5 až k Divine Tier. Hodnoty se ale můžou i zhoršit.", "exalt": "Přidá nové bonusy z Exalted poolu."}, "greater": "Všechny čtyři existují i jako <strong>Greater varianty</strong>, které fungují konkrétně na 6. a 7. bonus. Padají z portálových bossů — hlavně Elite a Super-Elite — a z Platoonu od P1000+.", "wfT": "Odemykání nových bonusů", "unconfT": "Postup není plně potvrzený", "unconfD": "Autor zdroje si není jistý, že je to správně — tohle je jeho současné chápání systému.", "wf": [["Odstraň existující bonusy", "Použij Orby of Annulment. Obvykle to znamená vyčistit nejdřív všech 7 slotů."], ["Použij Exalted Orby", "Ty tahají z úplně jiného poolu, včetně Portal Damage a Magic Poweru."], ["Přerolluj Chaos Orby", "Přerollne bonusy, ale item zůstane v Exalted poolu. Pozor — Chaos může bonusy strčit zpátky na normální a pak musíš znovu annulovat a exaltovat."], ["Doladi Divine Orby", "Jakmile trefíš silné bonusy, zvyšuj tiery. Cíl je Divine tier na každém bonusu."]], "newT": "Známé nové bonusy", "ignT": "Ignore Resistances je špička", "ignD": "Hodně silný, ale dostupný jen na bonusech 1 až 5. Pro bonusy 6 a 7 je volbou Boss Damage.", "expectT": "Srovnej si očekávání", "expectD": "Nečekej, že itemy vyladíš rychle. S dostatkem měny a trochou štěstí z nich budou extrémně silné kusy — ale systém je drahý, hodně závislý na náhodě a těžko se optimalizuje."}, "faq": {"lead": "Časté problémy a rychlé odpovědi.", "q": [["Hra nenaběhne", "Nejčastěji chybí C++ Redistributables. Nainstaluj je, nebo zkus čerstvě zapatchovat do úplně nové složky."], ["Chyba Security Violation", "Spustil se anticheat kvůli jinému programu. Známé příčiny: Windhawk, AutoHotkey, jiný antivirus než Windows Defender a dokonce i skladba na Spotify nebo panel prohlížeče, jehož název obsahuje známé jméno cheatu."], ["Změna PINu, deletion kódu nebo mailu", "Běž na <code>#bot-commands</code> na Discordu. Všechny příkazy tam fungují kromě změny hesla — tu musíš udělat v klientovi."], ["Jak upgradnu gear?", "Před levelem 300 nijak. Do té doby máš sílu jen z levelů a ze switchování bonusů."], ["Jak zvýším ranky skillů?", "Fisher NPC v Lobby, pravý horní roh mapy, prodává Grandmaster Stones a Rainbow Stones."], ["Co dělá Drop Chance?", "Zvyšuje šanci na item navíc z droppoolu monstra nebo Metinu. Nefunguje v portálech ani na chestech, takže je hlavně na farmení Shardů na levelovacích mapách."]], "srcT": "Zdroj", "srcD": "Komunitní průvodce pro Nihor2, postavený z psaných progression guidů, herních dat a hráčských logů. Tam, kde něco není potvrzené nebo otestované, je to poznamenáno přímo u toho.", "updT": "Data průvodce"}, "mnt": {"lead": "Společník, kterého koupíš u obchodnice se smíšeným zbožím za 150 milionů Yangu. Není to mount — nezpomaluje tě a staty, které dává, patří k největším jednotlivým upgradům ve hře vůbec.", "cap": "Okno Mount Companion na levelu 31", "costT": "Cena a kde ho koupíš", "costD": "150 milionů Yangu u obchodnice se smíšeným zbožím. Jednorázový nákup — všechno ostatní je už jen levelování a rozdělování bodů.", "capT": "Strop levelu a body", "capD": "Společník jde do levelu 150 a za každý level dostane 1 bod do atributů. Atributů je deset, každý má strop 20 bodů, takže vymaxovat všechno by stálo 200 bodů. Nikdy nedostaneš víc než 150 — zhruba tři čtvrtiny. Některé atributy prostě necháš prázdné, takže to plánuj podle svého buildu.", "calledT": "Jen když je vyvolaný", "calledD": "Všechny bonusy platí pouze tehdy, když je společník vyvolaný. Jakmile ho pošleš pryč, přijdeš o všechno.", "attrT": "Hodnoty atributů", "aH1": "Atribut", "aH2": "Za bod", "aH3": "Při 20 bodech", "aH4": "S Loyal ×1,75", "loyalT": "Násobitel Loyal Companion", "loyalD": "Na každém tooltipu je řádek <strong>Loyal Companion ×1,75</strong>. Ten násobitel se aplikuje navrch uvedeného efektu a právě on posouvá tahle čísla z dobrých na rozhodující. Sloupec ×1,75 výše je dopočítaný z herních hodnot za bod.", "slotT": "Sloty na equip a emblemy", "slotD": "Šest slotů na vybavení a tři na emblemy, odemykají se podle levelu společníka.", "sH1": "Slot", "sH2": "Odemkne se na", "unlockStart": "Od začátku", "whyT": "Proč ti to změní build", "whyD": "Podívej se na Critical Hit Chance: 20 bodů dá +150 % a s násobitelem Loyal se to dostane zhruba na +262 %. Endgame sekce tohohle průvodce chtějí 330 až 360 % critu pro permanentní crity v Heroic dungeonech, Platoonu a Nalantiru. Samotný společník pokryje většinu té mezery. Drop Chance s +25 % v základu je podobně velká položka a Drop Chance nemá reálný strop.", "tipT": "Zkratka pro rozdělování bodů", "tipD": "Shift + klik přidá 10 bodů naráz místo jednoho. K dispozici je taky tlačítko Reset points, pokud chceš build přestavět."}, "gear": {"lead": "Každý kus výbavy má vlastní žebříček upgradů a ty sahají hodně daleko za počáteční Soul Crystal set. Jeď každý sloupec popořadě — položky jsou seřazené od první k poslední, ne od nejlepší k nejhorší.", "wT": "Zbraň", "aT": "Armor", "setT": "Set šperků", "bT": "Opasek", "jT": "Sloty šperků", "sT": "Spirit Stones", "exoT": "Co znamená Exotic", "exoD": "Exotic je upgrade tier aplikovaný na existující item, ne samostatný drop. Objevuje se na zbraních, armoru, špercích, Spirit Stones a dokonce i na Ring of Blessing. U Spirit Stones má autorův vlastní endgame snapshot <strong>Monster, Cooldown, Crit, Block, Dodge a Haste všechny na +12 Exotic</strong> — to je cíl, ne třešnička.", "orderT": "Rozumné pořadí", "orderD": "Nejdřív dostaň celý Soul Crystal set na +3, včetně zbraně a armoru. Zbraň a armor exotikni dřív, než se poženeš za P50 nebo Kyanitem. Spirit Stones vytáhni plošně na +12, pak ty důležité exotikni. Sloty na šperky mají přednost před kvalitou šperků.", "milesT": "Paragon milníky", "milesD": "Průvodce je sleduje jako kontrolní body. Každý level navíc dává +2 Attack Value, takže i samotné grindování levelů ti zvedá damage — z P1 na P100 je to zhruba 10 až 20 % rozdíl."}, "boost": {"lead": "Skill Booster je největší jednotlivý early upgrade damage ve hře a musíš si ho vycraftit sám. Nic jiného v early checklistu se tomu nepřiblíží.", "prioT": "Priorita číslo jedna", "prioD": "Zdrojový průvodce je v tomhle jednoznačný: mít připravený Skill Booster je tvůj první cíl, přednostně před vším ostatním. Zvedne ti damage o hodně. Vycraftni ho a jakmile ho máš, vytáhni ho na M-1.", "ladderT": "Žebříček upgradů", "ladderD": "Každý krok je reálný skok. Požadavky pro pozdní obsah jsou psané v tierech boosteru, ne v gearu.", "gateT": "Co který tier odemkne", "g1": "Nutné, abys vůbec mohl do P1000+ obsahu", "g3": "Platoon", "g7": "Nalantir", "whichT": "Který booster", "whichD": "Jeden na build, odpovídající tvému hlavnímu damage skillu. Některé buildy potřebují dva — Dragon jede Talisman plus Starfall — jiným stačí jeden. Pokud hraješ mix build, boostni ten skill, na kterém ten mix reálně stojí."}, "rob": {"lead": "Ring of Blessing je procentuální item, který se upgraduje po krocích, a každý krok má hodnotu rovných 20 % Skill Damage. Při 100 % je to 200 Skill Damage z jediného itemu.", "ladderT": "Kroky upgradu", "ladderD": "Na early game ti stačí 10 až 30 %. Za zbytkem se žeň, až budeš mít vyřešený Skill Booster.", "dexT": "Dexterity of Smith", "dexD": "Ring of Blessing bere bonus zvaný Dexterity of Smith. Dva dobré staty můžou stačit, ale víc je líp. Maximální hodnoty níže.", "dH1": "Stat", "dH2": "Maximum", "dexNote": "Prsten s damage statem tvojí classy plus Attack Value může být lepší než prsten jen s vyšším procentem class damage. Neposuzuj to podle jednoho čísla.", "curseNote": "Curse Damage je taky možnost, pokud jedeš plný Blue build."}, "glo": {"lead": "Nihor2 si bere hodně slovníku z Metinu2 a přidává si vlastní. Když tě v tomhle průvodci něco zarazí, bude to nejspíš tady.", "h1": "Pojem", "h2": "Co to znamená", "d": {"yang": "Měna. Padá skoro ze všeho a platí se jí všechno.", "metin": "Kámen, který rozbíjíš. Rozbitím se spustí vlna monster a vypadne loot — většina farmení stojí právě na nich.", "shard": "Nejběžnější craftovací materiál na serveru. Budeš jich mít tisíce.", "upitem": "Upgradovací item. Potřebuješ ho, abys dostal gear z +0 směrem k +9.", "switch": "Přehazování bonusů na kusu gearu. Item si necháš, měníš jen to, co ti dává. Většina tvojí síly v early game pochází ze switchování, ne z nových dropů.", "emblem": "Šest nasaditelných itemů, které určují, jak se tvoje classa hraje. Výběr té šestice je největší rozhodnutí o tvojí postavě.", "paragon": "Levelovací systém, který přebírá po levelu 300. Píše se P350, P1000 a tak dál. Každý level navíc dává +2 Attack Value.", "stufe": "Stupeň obtížnosti portálu. Vyšší Stufe znamená těžší monstra a lepší odměny.", "booster": "Item, který násobí damage jednoho konkrétního skillu. Musíš si ho vycraftit. Je to největší jednotlivý early upgrade damage ve hře.", "dew": "Permanentní consumable, který jednou upgradneš a máš navždy — rychlost, zkušenosti, drop rate.", "soulcrystal": "Gear tier na levelu 80, na kterém všichni začínají endgame. Tvůj první pořádný set.", "pskill": "Skill vytažený na stupeň Perfect. Tvůj damage skill a všechny buffy se sem potřebují dostat.", "bounty": "Questovní truhla, kterou si vycraftíš a pak naplníš splněním úkolů. V early game jeden z lepších zdrojů emblemů.", "exotic": "Upgrade tier, který se nasadí na item, co už máš — není to samostatný drop.", "pity": "Itemy z Farm map, které utratíš u Fishera v Lobby."}}, "maps": {"lead": "Všechny mapy, co se objevují v bounty úkolech, ať víš, co existuje a zhruba v jakém pořadí to uvidíš.", "levelT": "Levelovací trasa, 1 → 300", "colonyT": "Colony mapy", "colonyD": "Otevřou se na levelu 300. Tohle jsou Paragon farmící revíry a bounty se mezi nimi točí.", "lateT": "Pozdější mapy", "lateD": "Objevují se v bounty úkolech, ale psaný guide je zatím nepokrývá — ber ten seznam jako mapu toho, co existuje, ne jako trasu.", "note": "Vytaženo z reálných názvů bounty úkolů, takže psaní sedí s tím, co vidíš ve hře."}}, "mountNew": "Jedna výjimka: Mount Companion, kterého prodává obchodnice se smíšeným zbožím, je úplně jiný systém a stojí za každý Yang. Viz sekce Mount Companion.", "overviewT": "Co v průvodci najdeš", "stageT": "Kde zrovna jsi?", "stages": {"all": "Zobrazit vše", "new": "Level 1–300", "fresh": "Čerstvá 300", "mid": "P350 – P1000", "end": "P1000+"}, "stageHint": "Vyber si fázi a guide schová to, co se tě zatím netýká.", "navgStart": "První kroky", "add": {"serumT": "Čím se companion leveluje", "serumD": "Companion Serum, které existuje ve dvou pásmech: <strong>[50-250]</strong> a <strong>[250-500]</strong>. Séra padají během hraní. Vedle nich uvidíš ještě <strong>Companion Scroll</strong>, <strong>Companion Bewitchment</strong>, <strong>Companion Enchantment</strong> a <strong>Companion Seal</strong>, které řeší zbytek upgradů companiona.", "spiritT": "Spirit Emblemy", "spiritD": "Samostatná řada emblemů mimo tvoji šestici. Známé jsou: <strong>Wisdom</strong>, <strong>Thorns</strong>, <strong>Lightning</strong>, <strong>Defense</strong> a <strong>Curses</strong>. Padají ze Spirit Emblem Chestů a jsou vzácné.", "boostNameT": "Boostery jsou na konkrétní skill", "boostNameD": "Žádný obecný item „Skill Booster\" neexistuje. Každý je navázaný na skill a padá na Levelu 1, třeba <strong>Lightning Throw Booster (Level 1)</strong> nebo <strong>Lightning Claw Booster (Level 1)</strong>. Chceš ten, co sedí na hlavní damage skill tvého buildu, a pak ho taháš nahoru po žebříčku M / G.", "undocT": "Dva systémy, ke kterým zatím guide není", "undocD": "Klient má okno <strong>Prisma</strong> a vestavěnou <strong>wiki</strong>, přičemž psaný guide nepokrývá ani jedno. Pokud jsi nový a někdo je zmíní, tady máš důvod, proč je níž nenajdeš."}}, "en": {"navg": {"basics": "Basics", "combat": "Combat", "endgame": "Endgame", "systems": "Systems", "help": "Help", "gearGrp": "Gear"}, "nav": {"start": "Start Here", "path": "Leveling Path", "at300": "Reaching 300", "kit": "Core Kit", "faq": "FAQ", "gear": "Gear Progression", "boost": "Skill Booster", "rob": "Ring of Blessing", "emb": "Emblems", "cls": "Class Ratings", "bld": "Meta Builds", "par": "Paragon Path", "por": "Portals", "pet": "Pets", "tal": "Talismans", "exp": "Expeditions", "pro": "Prophecies", "exa": "Exalted Attributes", "mnt": "Mount Companion", "glo": "Words you'll see", "maps": "Maps"}, "hero": {"tag": "Player Guide", "title": "From level one to <b>Nalantir</b>", "sub": "Nihor2 plays nothing like standard Metin2. Levels run to 300, then Paragon carries the rest of the game. This is the whole route.", "s1": "Level range", "s2": "Paragon ceiling", "s3": "Build variants", "s4": "Base emblems"}, "s": {"start": {"lead": "Three things to know before you kill anything.", "mountT": "Never play on a mount", "mountD": "Mounts are not useful on this server and never will be. On a mount you move and attack slower, because extra movement and attack speed values get cut off.", "emptyT": "The server looks empty — it isn't", "emptyD": "Most players are AFK in the Lobby Map, farming higher-level maps, or inside dungeons. The early maps are quiet by design.", "fastT": "Fastest starter", "fastD": "Archer with daggers is currently the easiest class to push through the early game. Every class is viable though — play what you enjoy.", "timeT": "Time to 300", "timeD": "Roughly 60 to 90 minutes of active play. The route is linear and there is very little to decide along the way.", "gearT": "Don't buy gear yet", "gearD": "You drop nothing meaningful before Grotto of Exile at Lv. 75. Quest gear carries you fine — save the Yang."}, "path": {"lead": "Follow this in order. If your damage is too low on a map, drop back one step rather than forcing it.", "steps": [["Open the starter chest", "Use the Violet Potion and equip the XP Ring straight away."], ["Farm Map 1 to Lv. 5–20", "Nothing complicated here."], ["Switch Average + Monster", "Slots 6 and 7, using the Switchbot on <kbd>F6</kbd>."], ["Pick your subclass, move to Map 2", "Already Lv. 20+? Skip straight to Valley of Seungryong."], ["Farm White Eid Bozos to Lv. 30", "Portal menu opens with <kbd>F5</kbd> or the green ring in the taskbar."]], "routeT": "The route", "r": {"start": "Starter chest, then White Eid Bozos in Valley of Seungryong.", "sd1": "Use the Perma Boni Adder from the Level 1 chest on entry. Make sure every equipment piece carries 5 bonuses. Optionally switch some to EXP for faster levelling.", "sd2": "Buy a <strong>Lv. 55 Royal Armor +9</strong> and <strong>Lv. 55 Shield +9</strong> from the Armor Shop Dealer before you enter.", "g1": "Your first real upgrades: Lv. 75 weapons, Lv. 70 armor, accessories. Good moment to prepare 2–3 equipment sets for early dungeons.", "g2": "More of the same. Keep moving.", "oc": "Pure levelling ground, nothing special drops.", "nb": "If damage is lacking, stay in Old City a while longer.", "gc": "Same rule — fall back to Nephrite Bay if you're struggling.", "tm": "Final stretch to 300."}, "dieT": "Dying often?", "dieD": "Put TP on Hit bonuses on a few gear pieces. There are no major equipment upgrades before Lv. 75, so switching bonuses is the only lever you have."}, "at300": {"lead": "Level 300 is where the real game starts. Levelling ends, Paragon begins.", "unlockT": "What unlocks", "unlock": ["Private messaging other players", "Access to the Lobby Map", "The first two Farm Maps", "Spirit Stone drops from Metins", "Gear upgrading — impossible before 300"], "dropT": "Farm Map drops", "pity": "Pity Items", "fisherT": "The Fisher NPC", "fisherD": "Spend Pity Items at the Fisher in the Lobby — top right corner of the map. This is where Grandmaster Stones and Rainbow Stones come from, which raise your skill ranks.", "farmT": "Where to farm Yang and up-items", "farm": ["Low dungeons — Razador, Nemere, Jotun Thrym, Blue Death", "Bounties — World and Dungeon variants", "Owl Runs — emblem chests and materials", "Grinding the early Farm Maps <em>optional</em>"]}, "kit": {"lead": "The shared baseline every class works toward before class-specific progression begins. Order is a suggestion — market prices shift it.", "utilT": "Permanent utility", "gearT": "Gear baseline", "setbonus": "set bonus", "emb6": "All 6 Emblems of your build", "anyroll": "any roll", "bigT": "The three that matter most", "bigD": "<strong>Gold Medal</strong> — much more Yang. <strong>Violet Potion</strong> — large movement speed gain at higher upgrades. <strong>Thief's Gloves</strong> — drop chance is never truly capped, so it keeps scaling. Note that drop chance does not work on chests or inside Portals.", "switchT": "Skills and switching", "sw": ["P-Skill for the build you play", "All buff skills on P", "Weapon and Armor switched to <strong>Skill Damage (27%)</strong> or <strong>Average Damage (60%)</strong>, depending on build", "Remaining equipment switched to suit your build"], "autoT": "Auto loot", "auto": [["Get Companion's Reading", "Buy it or craft it in the Crafting Menu."], ["Summon your pet", "Any pet works."], ["Drag the item onto the pet seal", "Auto loot is now active."]], "stoneT": "Spirit Stones", "freeT": "Free to experiment", "freeD": "Spirit Stones are equipped separately — not bound to weapons or armor, removable at any time, and swapping always succeeds. There is zero risk in trying setups. Open the extra window inside your inventory with III.", "offT": "Offensive", "defT": "Defensive / utility", "dgT": "Dungeon bonus setups", "dgH1": "Dungeon", "dgH2": "Strong Against bonuses"}, "emb": {"lead": "Emblems are equippable items that change how your class plays. They are the single biggest decision you make about your character.", "cap": "What emblems are, where they drop, and how rolls work", "q1": "What are they?", "a1": "Equippable items that greatly change the gameplay of your class. Each class has 2 emblem sets of 6 pieces each, and you can combine those pieces however you want.", "q2": "Where to get them", "a2": "From Emblem Chests, craftable in the Crafting Menu (F10) or dropped by Blue Death, Owl Dungeon and Bounty Chests. Each chest gives 1 random emblem out of 96 base emblems.", "q3": "Rolls", "a3": "Emblems have internal rolls, shown in orange. These cannot be changed after the drop — a good roll is a different item from a bad one."}, "cls": {"lead": "Ratings from 0 to 10, as judged by the guide author. Scaleability covers more than raw damage — AoE, projectiles and so on.", "h": {"cls": "Class", "set": "Emblem Set", "mob": "Mob Clear", "st": "Single Target", "metin": "Metin", "spd": "Speed", "fun": "Fun", "note": "Notes"}, "n": {"chill": "Chill playstyle", "mix51": "Needs a 5|1 mix", "untested": "Untested", "bestst": "One of the best single-target builds right now", "needgear": "Needs good gear and emblems", "brain": "If your brain and eyes can handle it", "portal": "Good portal class", "twohit": "Needs to at least 2-hit to feel good", "burst": "Strong burst, medium clear", "mix": "Best played in a mix", "rework": "Not enough info after reworks"}, "opT": "Read this as opinion", "opD": "These numbers are the author's personal judgement, not measured benchmarks. Treat them as a starting point rather than a tier list."}, "bld": {"lead": "Currently played emblem sets. Emblem names stay in English because that is how they appear in-game.", "x": {"unconf": "Not fully confirmed — this is the setup seen most often.", "msura": "Swaps Dark Armor for Strengthened Flames once you pass 300 INT.", "norain": "Nobody really plays the Rain build any more after the recent Chain changes.", "dragearly": "Get burn damage early, ideally from the Burn Damage Spirit Emblem or Pet Artifacts at P250+. This carries the early game.", "dragstar": "Shifts focus from Burn Damage toward Magic Power and Starfall. Likely the stronger damage option.", "dragburn": "Preference-based alternative — more relaxed to play, slightly lower ceiling."}}, "par": {"lead": "After 300, progression runs through Paragon levels. Each level also grants +2 Magical Attack Value, and P1000 gives +50 MDEF.", "g": {"g250": "Unlocks Pet Equipment with real bonuses — the first major power spike. Also where Ring of Blessing dexterities become worth chasing.", "g350": "Great Portal opens. Taliko becomes available, with entry tickets farmed in Zodiac Desert. You can now farm the first two Paragon maps properly.", "g500": "The main levelling engine from here on. Reach P500 in Zodiac Desert, then move into Mythic Portal levelling.", "g650": "Elite Portals bring Elite and Super-Elite enemies. Ape God opens for Belt and Pet Bonus Adders. Valley of Apes carries you to P650+ easily.", "g1000": "Heroic Razador, Nemere and Jotun become entirely new runs, plus Platoon. Primary source of Sigils and attribute switching orbs.", "g1500": "The current ceiling of documented content."}, "lvlT": "Where to level", "rangeH": "Range", "methH": "Method", "m1": "Mythic Portals, Stufe ~100–400", "m2": "Run Mythic from Stufe 1 as high as you can — ideally 10k+. Nets ~50–100 levels per run", "m3": "Orc Valley level map again", "m4": "Paragon Scrolls dropped from Portals", "gearT": "Gear before levels", "gearD": "If you can't clear Stufe 100+, work on your gear instead of pushing to P1000. Levels you can't use don't open anything."}, "por": {"lead": "Portals are infinitely repeatable and stay relevant forever. You kill until 100% completion — roughly 2,000 monsters, each Metin worth 10% — then a boss spawns. Kill it, repeat, and the Stufe climbs.", "p": {"pgreat": "The classic version. Stufe increases by one per completion.", "pmyth": "Same loop, but Stufe climbs by more than one each time and it is harder overall. Best option for levelling.", "pelite": "Like Mythic, plus you must kill 25 Elite enemies — the ones glowing yellow — on top of reaching 100%."}, "seT": "Super-Elite and the Fanny Pack", "seD": "On the <strong>first</strong> map of every started Elite Portal — and only the first — there is a small chance a Super-Elite monster spawns, glowing red. It drops heavily, including the chase item: the <strong>Fanny Pack</strong>, which increases Pet Equipment slots. That drop chance does not scale with Stufe, so it is always the same. Check whether one spawned using a <strong>Magical Orb</strong>, crafted from Portal Shards.", "giveT": "What Portals give you", "give1": ["Paragon levels", "Green / Blue Gems <em>up to 75% Skill or 150% Average</em>", "Lapislazuli for Prophecies", "Adders and Switchers for the 8th bonus"], "give2": ["Divine Orbs and switching currency", "Exotic Equipment", "Exotic Stones", "Pet Equipment"], "hardT": "Starting out hurts", "hardD": "This content is very difficult at first — monsters hit hard and have huge TP pools. The single biggest lever: <strong>get Portal Damage Pet Artifacts.</strong>"}, "pet": {"lead": "Pets become available at Paragon 250 and quickly turn into one of the strongest systems in the game. At higher levels your pet provides the majority of your damage.", "cap1": "Pet fundamentals", "cap2": "Pet equipment slots", "statT": "Stat points and class picks", "sH1": "Stat", "sH2": "Per point", "cH1": "Class / Build", "cH2": "Best pet stat", "rollT": "Internal rolls matter enormously", "rollD": "Every pet bonus has an internal roll. A Level 500 pet with Portal Damage might have 100% — or 300%. Two identical-looking pets are not the same pet.", "goodT": "Good Level 500 rolls", "treeT": "Pet Mastery", "cycT": "This path is Cyclone-specific", "cycD": "The source guide only documents the Cyclone mastery order. Do not apply it blindly to other classes.", "cap3": "The pet mastery tree, in game", "openT": "Opening order", "maxT": "Then max, in this order"}, "tal": {"lead": "Talismans grant a Strong vs. Element bonus plus one offensive bonus. There are six, you equip one of each, and a seventh slot holds the Talisman Core.", "cap": "In-game tooltip", "h1": "Talisman", "h2": "Elemental (+200)", "h3": "Secondary (+200)", "facts": ["Crafted in the Crafting Menu <em>Shards + a lot of Yang</em>", "Some cost up to 2.5kkk Yang", "Upgradeable to +200", "+0 → +200 costs 20,100 Soulstones <em>plus many Shards</em>", "Elemental bonus applies to monsters with the matching element — check the icon next to their HP bar", "Does not appear to work inside Portals"], "coreT": "The Core scales off every Talisman", "coreD": "Every 50 levels raises a Talisman's SR rank, and the Core bonus depends on the SR rank of <strong>all six</strong>. You would need every Talisman at SR1 to gain the better Core bonus — and the Core gives nothing at all unless all six are equipped.", "adviceT": "Early advice", "adviceD": "Just craft the Talismans and upgrade them a little. Do not chase high upgrades or the Core early — the system gets expensive fast."}, "exp": {"lead": "A long-term background system built around levelling Settlers. Their bonuses scale with level, which makes a well-levelled low-tier Settler far better than its base stats suggest.", "steps": [["Get around 3 Uncommon Settlers", "Depending on your Settler and Pet slots. Try to cover Swift, Mighty and Lucky at least once each."], ["Farm 1-hour Easy until Level 3+", "Short runs level several Settlers quickly while keeping success rates reliable."], ["Switch almost entirely to 3-hour Hard", "This becomes your main expedition farm for a significant stretch of progression."], ["Collect the key rewards", "Full Adanos, Belt Switcher, Taskals to use or sell, expedition pets, main Settlers at Level 6+."], ["Move to 6-hour Hard", "Run these until your team hits 60% success on 12-hour Hard."], ["Then 12-hour, then 24-hour Hard", "Same rule — move up once the next tier reaches roughly 60% success."]], "perkT": "Settler perks", "pH1": "Perk", "pH2": "Effect", "perkN": {"swift": "Swift", "mighty": "Mighty", "lucky": "Lucky", "shadow": "Shadow", "sage": "Sage", "divine": "Divine", "phoenix": "Phoenix"}, "perkD": {"swift": "Reduces expedition duration", "mighty": "Increases expedition success chance", "lucky": "Improves loot and rare item discovery", "shadow": "Mix of improved loot and speed or success, depending on the Settler", "sage": "Increases XP obtained from expeditions", "divine": "Improves multiple statistics at once — one of the strongest general-purpose perks", "phoenix": "Prevents XP loss from failed expeditions"}, "setT": "Settler list", "sH1": "Tier", "sH2": "Settler", "sH3": "Perk", "sH4": "Base value", "tier": {"common": "Common", "uncommon": "Uncommon"}, "ruleT": "Two rules that save time", "ruleD": "Prioritise <strong>levels over replacing Settlers</strong> — perks scale with level, so a well-levelled lower tier stays useful for a long time. And treat <strong>success chance as your gate</strong>: if the next tier has a low success rate, keep farming the previous duration. Around 60% is the sensible point to move up."}, "pro": {"lead": "Open the Prophecy window with Ctrl + P. Each Lapislazuli gives one random Prophecy. Lapis drops from monsters in any Portal — the Portal level does not matter and the drop chance is always the same.", "h1": "Prophecy", "h2": "Effect", "n": {"emblemmad": "Emblem Madness", "bountyhunt": "Bounty Hunter", "nemere": "Nemere's Dream", "razador": "Razador's Nightmare", "outpower": "Outstanding Power", "outwis": "Outstanding Wisdom", "blacksmith": "Master Blacksmith", "luck": "Exceptional Luck", "blessing": "Jinteia's Blessing", "biggame": "Big-Game Hunting", "astral": "Astral Convergence", "magicwords": "Magic Words"}, "d": {"emblemmad": "Guarantees an Emblem Chest from your next Blue Death Chest", "bountyhunt": "Doubles rewards from the next Bounty Chest", "nemere": "Your next Nemere kill drops Eternal Ice", "razador": "Your next Razador kill drops Eternal Fire", "outpower": "Next permanent enchant on weapon or armor gives at least 150 Average Damage", "outwis": "Next permanent enchant on weapon or armor gives at least 100 Skill Damage", "blacksmith": "Your next forging attempt requires no materials", "luck": "Your next forging attempt is guaranteed to succeed", "blessing": "Next successful forge skips a level — +7 goes straight to +9", "biggame": "Guarantees a Super-Elite in your next Elite Portal", "astral": "Your next Divine Orb has a better outcome", "magicwords": "Adds a random 9th attribute — exists for almost any equipment item"}, "more": "Many more strong Prophecies exist beyond this list."}, "exa": {"lead": "A special attribute system tied to a new switching currency. It lets you roll far higher values, exceed normal caps and unlock attributes that do not exist in the normal pool. Instead of +12 INT on a shield you might reach +40.", "orbN": {"chaos": "Chaos Orb", "annul": "Orb of Annulment", "divine": "Divine Orb", "exalt": "Exalted Orb"}, "orbD": {"chaos": "Rerolls bonuses within the Exalted pool.", "annul": "Removes an existing bonus from an item.", "divine": "Raises the value tier of existing bonuses, past the normal Tier 5 cap and up to Divine Tier. Values can also get worse.", "exalt": "Adds new bonuses from the Exalted pool."}, "greater": "All four also exist as <strong>Greater variants</strong>, which work specifically on the 6th and 7th bonuses. They drop from Portal Bosses — mainly Elite and Super-Elite — and from Platoon at P1000+.", "wfT": "Unlocking new bonuses", "unconfT": "Workflow not fully confirmed", "unconfD": "The source author is not certain this is correct — it is their current understanding of the system.", "wf": [["Remove existing bonuses", "Use Orbs of Annulment. Usually this means clearing all 7 slots first."], ["Apply Exalted Orbs", "These pull from a completely different pool, including Portal Damage and Magic Power."], ["Reroll with Chaos Orbs", "Rerolls while keeping the item in the Exalted pool. Careful — Chaos can push bonuses back to normal, and then you annul and exalt again."], ["Min-max with Divine Orbs", "Once you hit strong bonuses, raise the tiers. The goal is Divine-tier stats on every bonus."]], "newT": "Known new bonuses", "ignT": "Ignore Resistances is the standout", "ignD": "Very strong, but only available on bonuses 1 through 5. For bonuses 6 and 7, Boss Damage is the pick.", "expectT": "Set your expectations", "expectD": "Do not expect to perfect items quickly. Invest enough currency and get lucky and these become extremely strong — but the system is expensive, RNG-heavy and hard to optimise."}, "faq": {"lead": "Common problems and quick answers.", "q": [["Game won't start", "Most often missing C++ Redistributables. Install them, or try a fresh patch into a brand new folder."], ["Security Violation error", "The anticheat triggered on another program. Known causes: Windhawk, AutoHotkey, antivirus other than Windows Defender, and even a Spotify track or browser tab whose title contains a known cheat name."], ["Change PIN, deletion code or email", "Go to <code>#bot-commands</code> in the Discord. Every command works there except changing your password — that has to be done in the client."], ["How do I upgrade gear?", "You can't before Level 300. Until then all your strength comes from levels and from switching bonuses."], ["How do I raise skill ranks?", "The Fisher NPC in the Lobby, top right corner of the map, sells Grandmaster Stones and Rainbow Stones."], ["What does Drop Chance do?", "Increases your chance of an extra item from a monster or Metin drop pool. It does not work in Portals or on chests, so it is mainly for farming Shards on level maps."]], "srcT": "Source", "srcD": "Community guide for Nihor2, built from the written progression guides, in-game data and player logs. Where something is unconfirmed or untested, that is noted in place.", "updT": "Guide data"}, "mnt": {"lead": "A companion bought from the General Goods merchant for 150 million Yang. It is not a mount — it does not slow you down, and the stats it grants are among the largest single upgrades available anywhere in the game.", "cap": "The Mount Companion window at Level 31", "costT": "Cost and where", "costD": "150 million Yang from the General Goods merchant. A single purchase — everything after that is levelling and point allocation.", "capT": "Level cap and points", "capD": "The companion levels to 150 and earns 1 attribute point per level. Ten attributes exist, each capped at 20 points, so maxing everything would take 200 points. You only ever get 150 — roughly three quarters. You will have to leave some attributes empty, so plan around your build.", "calledT": "Only while summoned", "calledD": "Every bonus applies only while the companion is called. Dismiss it and you lose all of it.", "attrT": "Attribute values", "aH1": "Attribute", "aH2": "Per point", "aH3": "At 20 points", "aH4": "With Loyal ×1.75", "loyalT": "The Loyal Companion multiplier", "loyalD": "Every tooltip carries a <strong>Loyal Companion ×1.75</strong> line. That multiplier applies on top of the listed effect, which is what turns these numbers from good into decisive. The ×1.75 column above is calculated from the in-game per-point values.", "slotT": "Equipment and emblem slots", "slotD": "Six equipment slots and three emblem slots, unlocking as the companion levels.", "sH1": "Slot", "sH2": "Unlocks at", "unlockStart": "From the start", "whyT": "Why this changes your build", "whyD": "Look at Critical Hit Chance: 20 points gives +150%, and with the Loyal multiplier that reaches roughly +262%. The endgame sections of this guide ask for 330% to 360% crit for permanent crits in Heroic Dungeons, Platoon and Nalantir. The companion alone covers most of that gap. Drop Chance at +25% base is similarly large, and Drop Chance has no real cap.", "tipT": "Point allocation shortcut", "tipD": "Shift + click adds 10 points at once instead of one. There is also a Reset points button if you want to rebuild."}, "gear": {"lead": "Every piece of equipment has its own upgrade ladder, and they run a long way past the starting Soul Crystal set. Work down each column in order — the entries are listed from first to last, not best to worst.", "wT": "Weapon", "aT": "Armor", "setT": "Jewellery set", "bT": "Belt", "jT": "Jewellery slots", "sT": "Spirit Stones", "exoT": "What Exotic means", "exoD": "Exotic is an upgrade tier applied to an existing item, not a separate drop. It appears on weapons, armor, jewellery, Spirit Stones and even the Ring of Blessing. On Spirit Stones the guide's own endgame snapshot runs <strong>Monster, Cooldown, Crit, Block, Dodge and Haste all at +12 Exotic</strong> — that is the target, not a nice-to-have.", "orderT": "Sensible order", "orderD": "Get the whole Soul Crystal set to +3 first, including weapon and armor. Exotic your weapon and armor before chasing P50 or Kyanit. Push Spirit Stones to +12 across the board, then Exotic the important ones. Jewellery slots come before jewellery quality.", "milesT": "Paragon milestones", "milesD": "The guide tracks these as checkpoints. Each level also gives +2 Attack Value, so even grinding levels alone moves your damage — P1 to P100 is roughly a 10 to 20% difference."}, "boost": {"lead": "The Skill Booster is the single biggest early damage upgrade in the game, and you have to craft it yourself. Nothing else in the early checklist comes close.", "prioT": "Priority one", "prioD": "The source guide is blunt about this: getting your Skill Booster ready is your first goal, ahead of everything else. It boosts your damage by a lot. Craft it, then upgrade it to M-1 as soon as you have it.", "ladderT": "Upgrade ladder", "ladderD": "Each step is a real jump. The gating for late content is written in booster tiers, not gear.", "gateT": "What each tier unlocks", "g1": "Needed to move into P1000+ content at all", "g3": "Platoon", "g7": "Nalantir", "whichT": "Which booster", "whichD": "One per build, matching your main damage skill. Some builds need two — Dragon runs Talisman plus Starfall, for example — while others only need one. If you play a mix build, boost the skill the mix is actually built around."}, "rob": {"lead": "The Ring of Blessing is a percentage-based item that upgrades in steps, and each step is worth a flat 20% Skill Damage. At 100% that is 200 Skill Damage from this one item.", "ladderT": "Upgrade steps", "ladderD": "10% to 30% is enough for the early game. Chase the rest once your Skill Booster is sorted.", "dexT": "Dexterity of Smith", "dexD": "The Ring of Blessing takes a bonus called Dexterity of Smith. Two good stats may be enough, but more is better. Maximum values below.", "dH1": "Stat", "dH2": "Maximum", "dexNote": "A ring with your class damage stat plus Attack Value can beat a ring with a higher class damage percentage alone. Don't judge on one number.", "curseNote": "Curse Damage is also an option if you run a full Blue build."}, "glo": {"lead": "Nihor2 borrows a lot of vocabulary from Metin2 and then adds its own. If a word in this guide stops you, it's probably here.", "h1": "Term", "h2": "What it means", "d": {"yang": "The currency. Dropped by nearly everything, used for everything.", "metin": "A stone you break. Breaking one spawns a wave of monsters and drops loot — most farming is built around them.", "shard": "The most common crafting material on the server. You will have thousands.", "upitem": "An upgrade item. Needed to take gear from +0 toward +9.", "switch": "Rerolling the bonuses on a piece of gear. You keep the item, you change what it gives you. Most of your early power comes from switching, not from new drops.", "emblem": "Six equippable items that decide how your class plays. Picking your six is the biggest decision you make about your character.", "paragon": "The level system that takes over after 300. Written P350, P1000 and so on. Each level also gives +2 Attack Value.", "stufe": "A portal's difficulty step. Higher Stufe means harder monsters and better rewards.", "booster": "An item that multiplies one specific skill's damage. You craft it. It is the single biggest early damage upgrade in the game.", "dew": "A permanent consumable you upgrade once and keep forever — speed, experience, drop rate.", "soulcrystal": "The Lv. 80 gear tier everyone starts endgame on. Your first real set.", "pskill": "A skill raised to Perfect grade. Your damage skill and all your buffs want to get here.", "bounty": "A quest chest you craft, then fill by completing tasks. One of the better sources of emblems early.", "exotic": "An upgrade tier applied on top of an item you already own, not a separate drop.", "pity": "Items from the Farm Maps that you spend at the Fisher NPC in the Lobby."}}, "maps": {"lead": "Every map that shows up in world bounty tasks, so you know what exists and roughly in what order you'll see it.", "levelT": "Levelling route, 1 → 300", "colonyT": "Colony maps", "colonyD": "Opened at Level 300. These are the Paragon farming grounds, and bounties cycle through them.", "lateT": "Later maps", "lateD": "These appear in bounty tasks but aren't covered by the written guide yet — treat the list as a map of what's out there, not as a route.", "note": "Pulled from real bounty task names, so the spelling matches what you see in game."}}, "mountNew": "One exception: the Mount Companion sold by the General Goods merchant is a different system entirely, and it is worth every Yang. See the Mount Companion section.", "overviewT": "What's in this guide", "stageT": "Where are you right now?", "stages": {"all": "Show everything", "new": "Level 1–300", "fresh": "Just hit 300", "mid": "P350 – P1000", "end": "P1000+"}, "stageHint": "Pick your stage and the guide hides what doesn't apply to you yet.", "navgStart": "First steps", "add": {"serumT": "How the companion levels", "serumD": "Companion Serum, which comes in two bands: <strong>[50-250]</strong> and <strong>[250-500]</strong>. Serums drop while you play. Alongside them you'll see <strong>Companion Scroll</strong>, <strong>Companion Bewitchment</strong>, <strong>Companion Enchantment</strong> and <strong>Companion Seal</strong>, which handle the rest of the companion's upgrades.", "spiritT": "Spirit Emblems", "spiritD": "A separate emblem line from your build's six. Known ones: <strong>Wisdom</strong>, <strong>Thorns</strong>, <strong>Lightning</strong>, <strong>Defense</strong> and <strong>Curses</strong>. They come out of Spirit Emblem Chests and are rare.", "boostNameT": "Boosters are per-skill", "boostNameD": "There is no generic \"Skill Booster\" item. Each one is tied to a skill and drops at Level 1, for example <strong>Lightning Throw Booster (Level 1)</strong> or <strong>Lightning Claw Booster (Level 1)</strong>. You want the one matching your build's main damage skill, then you upgrade that one up the M / G ladder.", "undocT": "Two systems with no guide yet", "undocD": "The client has a <strong>Prisma</strong> window and a built-in <strong>wiki</strong>, neither of which the written guide covers. If you're new and someone mentions either, that's why you won't find them below."}}};
